mapper.select:
SELECT id, order_no, user_id, session_id, area_id, ticket_type, quantity, status,
       allocated_seats, fail_reason, create_time, update_time
FROM seat_allocation_task
WHERE status = 0 AND create_time < #{before}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE seat_allocation_task
SET allocated_seats = #{allocatedSeats}
WHERE order_no = #{orderNo} AND status = 0
